// ---------------------- Login ------------------------------
function LoginFlow({ onDone, onRequires2FA, onGoRecover, onGoRegister }) {
  const [email, setEmail] = useState("");
  const [pwd, setPwd] = useState("");
  const [err, setErr] = useState(null);
  const [loading, setLoading] = useState(false);

  const submit = async () => {
    setErr(null);
    if (!emailValid(email)) return setErr("E-mail inválido");
    if (pwd.length < 6) return setErr("Senha deve ter pelo menos 6 caracteres");
    setLoading(true);
    await new Promise((r) => setTimeout(r, 400));
    setLoading(false);
    onDone();
  };

  return (
    <section className="grid place-items-center">
      <Card className="w-full max-w-md">
        <CardHeader className="text-center">
          <img src={LOGO_DATA} alt="Logo do Nox" className="mx-auto h-20 w-20 rounded-full shadow-lg" />
          <CardTitle className="mt-4 text-2xl font-bold">Entrar no Nox</CardTitle>
          <p className="text-sm text-muted-foreground">Siga com e-mail ou provedor social</p>
        </CardHeader>
        <CardContent>
          <div className="grid gap-3" role="form" aria-label="Formulário de login">
            <div>
              <Label htmlFor="login-email">E-mail</Label>
              <Input id="login-email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="voce@exemplo.com" aria-invalid={!!err && !emailValid(email)} />
            </div>
            <div>
              <Label htmlFor="login-pwd">Senha</Label>
              <Input id="login-pwd" type="password" value={pwd} onChange={(e) => setPwd(e.target.value)} placeholder="••••••" aria-invalid={!!err && pwd.length < 6} />
            </div>
            {err && <p className="text-sm text-red-500" role="alert"><Lock className="inline h-4 w-4 mr-1"/>{err}</p>}
            <Button className="w-full bg-gradient-to-r from-emerald-500 to-blue-600" onClick={submit} disabled={loading} aria-busy={loading}>
              <LogIn className="mr-2 h-4 w-4"/>{loading ? "Entrando…" : "Entrar"}
            </Button>
            <div className="flex justify-between text-xs text-muted-foreground">
              <button className="underline" onClick={onGoRecover} aria-label="Recuperar senha">Esqueceu a senha?</button>
              <button className="underline" onClick={onGoRegister} aria-label="Criar conta">Criar conta</button>
            </div>
          </div>
          <div className="mt-4 grid gap-2" aria-label="Login social">
            <Button variant="outline" className="w-full" onClick={submit}><Chrome className="mr-2 h-4 w-4"/> Entrar com Google</Button>
            <Button variant="outline" className="w-full" onClick={submit}><Apple className="mr-2 h-4 w-4"/> Entrar com Apple</Button>
          </div>
          <div className="mt-4 flex items-center gap-2 text-xs text-muted-foreground">
            <ShieldCheck className="h-4 w-4"/> Senhas são criptografadas e 2FA é suportado.
          </div>
        </CardContent>
      </Card>
    </section>
  );
}

// ---------------------- Register ---------------------------
function RegisterFlow({ onDone, onBack }) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [pwd, setPwd] = useState("");
  const [agree, setAgree] = useState(false);
  const [err, setErr] = useState(null);

  const s = strength(pwd);

  const submit = async () => {
    setErr(null);
    if (!name.trim()) return setErr("Informe seu nome");
    if (!emailValid(email)) return setErr("E-mail inválido");
    if (s < 3) return setErr("Senha fraca: use maiúsculas, números e símbolos");
    if (!agree) return setErr("Você precisa aceitar os termos");
    await new Promise((r) => setTimeout(r, 400));
    onDone(); // segue para 2FA
  };

  return (
    <section className="grid place-items-center">
      <Card className="w-full max-w-md">
        <CardHeader className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={onBack}><ArrowLeft className="h-4 w-4"/></Button>
          <CardTitle>Criar conta</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid gap-3">
            <div>
              <Label htmlFor="reg-name">Nome</Label>
              <Input id="reg-name" value={name} onChange={(e) => setName(e.target.value)} placeholder="Seu nome" />
            </div>
            <div>
              <Label htmlFor="reg-email">E-mail</Label>
              <Input id="reg-email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="voce@exemplo.com" />
            </div>
            <div>
              <Label htmlFor="reg-pwd">Senha</Label>
              <Input id="reg-pwd" type="password" value={pwd} onChange={(e) => setPwd(e.target.value)} placeholder="••••••" />
              <PasswordMeter value={s} />
            </div>
            <div className="flex items-center gap-2 text-sm">
              <Switch id="agree" checked={agree} onCheckedChange={setAgree} />
              <Label htmlFor="agree">Concordo com os termos e política</Label>
            </div>
            {err && <p className="text-sm text-red-500" role="alert">{err}</p>}
            <Button className="w-full bg-gradient-to-r from-emerald-500 to-blue-600" onClick={submit}><UserPlus className="mr-2 h-4 w-4"/> Criar conta</Button>
          </div>
        </CardContent>
      </Card>
    </section>
  );
}

function PasswordMeter({ value }) {
  const labels = ["Muito fraca", "Fraca", "Média", "Forte", "Excelente"];
  const pct = Math.min(100, (value / 5) * 100);
  const label = labels[Math.max(0, value - 1)] || "Muito fraca";
  return (
    <div className="mt-2">
      <div className="h-2 w-full rounded bg-slate-300 dark:bg-slate-700 overflow-hidden">
        <div className={`h-2 transition-all rounded ${value < 3 ? "bg-red-500" : value < 4 ? "bg-yellow-500" : "bg-emerald-500"}`} style={{ width: `${pct}%` }} />
      </div>
      <p className="text-xs text-muted-foreground mt-1">Força da senha: {label}</p>
    </div>
  );
}

// ---------------------- Recover ----------------------------
function RecoverFlow({ onBack }) {
  const [email, setEmail] = useState("");
  const [sent, setSent] = useState(false);
  const send = async () => {
    if (!emailValid(email)) return alert("E-mail inválido");
    await new Promise((r) => setTimeout(r, 300));
    setSent(true);
  };
  return (
    <section className="grid place-items-center">
      <Card className="w-full max-w-md">
        <CardHeader className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={onBack}><ArrowLeft className="h-4 w-4"/></Button>
          <CardTitle>Recuperar senha</CardTitle>
        </CardHeader>
        <CardContent>
          {sent ? (
            <p className="text-sm text-muted-foreground"><Mail className="inline h-4 w-4 mr-1"/> Enviamos um link para {email}.</p>
          ) : (
            <div className="grid gap-3">
              <Label htmlFor="rec-email">E-mail</Label>
              <Input id="rec-email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="voce@exemplo.com" />
              <Button onClick={send} className="bg-gradient-to-r from-emerald-500 to-blue-600">Enviar link</Button>
            </div>
          )}
        </CardContent>
      </Card>
    </section>
  );
}

// ---------------------- 2FA -------------------------------
function TwoFA({ onConfirm, onBack }) {
  const [apiErr, setApiErr] = useState(null);
  const [code, setCode] = useState(Array(6).fill(""));
  const filled = code.every((c) => c.length === 1);
  return (
    <section className="grid place-items-center">
      <Card className="w-full max-w-md">
        <CardHeader className="flex items-center gap-2">
          <Button variant="ghost" size="sm" onClick={onBack}><ArrowLeft className="h-4 w-4"/></Button>
          <CardTitle>Verificação em duas etapas</CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground">Insira o código de 6 dígitos do seu app autenticador.</p>
          {apiErr && <p className="mt-2 text-sm text-red-500">{apiErr}</p>}
          <div className="mt-3 grid grid-cols-6 gap-2">
            {code.map((v, i) => (
              <Input key={i} inputMode="numeric" maxLength={1} className="text-center" value={v}
                     aria-label={`Dígito ${i + 1}`}
                     onChange={(e) => {
                       const c = e.target.value.replace(/\D/g, "").slice(0, 1);
                       setCode((old) => old.map((x, idx) => (idx === i ? c : x)));
                     }}
              />
            ))}
          </div>
          <div className="mt-4 flex gap-2">
            <Button disabled={!filled} onClick={async ()=>{
              setApiErr(null);
              const email = sessionStorage.getItem("nox_pending_email");
              const codeStr = code.join("");
              try {
                const { status, data } = await AuthAPI.verify2fa(email, codeStr);
                if (status >= 400) throw new Error(data?.error || "Código inválido");
                setTokens({ accessToken: data.accessToken, refreshToken: data.refreshToken });
                sessionStorage.removeItem("nox_pending_email");
                onConfirm();
              } catch(e){ setApiErr(e.message || "Falha na verificação"); }
            }} className="flex-1">Confirmar</Button>
            <Button variant="outline" className="flex-1">Reenviar código</Button>
          </div>
        </CardContent>
      </Card>
    </section>
  );
}

