// ---------------------- Assistant -------------------------
function Assistant({ onBack }) {
  const [msg, setMsg] = useState("");
  const [log, setLog] = useState([
    { role: "ai", text: "Bem-vindo! Escreva sua dúvida ou peça um sinal." },
  ]);
  const send = () => {
    if (!msg.trim()) return;
    const q = msg.trim();
    setMsg("");
    setLog((l) => [...l, { role: "user", text: q }]);
    setTimeout(() => setLog((l) => [...l, { role: "ai", text: "Exemplo: risco moderado, exposição recomendada 10% com stop em 3%." }]), 400);
  };
  return (
    <section className="grid gap-4">
      <div className="flex items-center gap-2">
        <Button variant="ghost" onClick={onBack}><ArrowLeft className="h-4 w-4"/></Button>
        <h2 className="text-xl font-semibold">IA Assistente</h2>
      </div>
      <Card>
        <CardContent className="pt-6 grid gap-3">
          <div className="space-y-2 max-h-80 overflow-auto pr-2">
            {log.map((m, i) => (
              <div key={i} className={`text-sm ${m.role === "ai" ? "text-emerald-400" : "text-primary"}`}><b>{m.role === "ai" ? "Nox" : "Você"}:</b> {m.text}</div>
            ))}
          </div>
          <div className="flex gap-2">
            <Input aria-label="Mensagem" value={msg} onChange={(e) => setMsg(e.target.value)} placeholder="Pergunte sobre um ativo ou peça ajuda…" />
            <Button onClick={send}>Enviar</Button>
          </div>
        </CardContent>
      </Card>
    </section>
  );
}

